WITH metrics AS (SELECT *, LAG(shipping_fee) OVER w_hist AS prev_shipping_fee, LEAD(discount) OVER w_hist AS next_discount, ROW_NUMBER() OVER w_hist AS event_seq, CORR(shipping_fee, discount) OVER (PARTITION BY store_id, channel) AS corr_shipping_fee_discount FROM orders WINDOW w_hist AS (PARTITION BY customer_id, status ORDER BY amount ASC, id ASC)) SELECT id, store_id, order_date, status, channel, amount, shipping_fee, prev_shipping_fee, next_discount, CASE WHEN status RLIKE '^(SHIPPED|PENDING)$' THEN 'GROUP_B' ELSE 'PRIORITY' END AS status_zone FROM metrics ORDER BY store_id ASC;
